    10	import pousada.Money;
    11	import pousada.Quote;
    12	
    13	/** A sequência de linhas comum a todos os documentos; cada documento muda só o que é dele. */
    14	final class DocumentLayout {
    15	
    16	    record Labels(String number, String room, String checkIn, String checkOut,
    17	                  String nightSingular, String nightPlural,
    18	                  String subtotal, String discount, String total,
    19	                  Function<BigDecimal, String> money, Function<LocalDate, String> date) {
    20	    }
    21	
    22	    static final Labels PORTUGUESE = new Labels("nº", "Quarto", "Entrada", "Saída",
    23	            "diária", "diárias", "Diárias", "Desconto", "Total",
    24	            v -> "R$ " + Money.brazilian(v),
    25	            d -> d.format(DateTimeFormatter.ofPattern("dd/MM/yyyy")));
    26	
    27	    static final Labels ENGLISH = new Labels("no.", "Room", "Check-in", "Check-out",
    28	            "night", "nights", "Nights", "Discount", "Total",
    29	            v -> "BRL " + Money.english(v),
    30	            LocalDate::toString);
    31	
    32	    private DocumentLayout() {
    33	    }
    34	
    35	    static String render(Labels l, String title, DocumentData data, List<String> partyLines, List<String> footerLines) {
    36	        Quote quote = data.quote();
    37	        List<String> lines = new ArrayList<>();
    38	        lines.add(title + " " + l.number() + " " + data.reservationId());
    39	        lines.addAll(partyLines);
    40	        lines.add(l.room() + ": " + data.room().number() + " (" + data.room().type() + ")");
    41	        lines.add(l.checkIn() + ": " + l.date().apply(data.checkIn())
    42	                + " | " + l.checkOut() + ": " + l.date().apply(data.checkOut())
    43	                + " | " + quote.nights() + " " + (quote.nights() == 1 ? l.nightSingular() : l.nightPlural()));
    44	        lines.add(l.subtotal() + ": " + l.money().apply(quote.subtotal()));
    45	        if (quote.discount().signum() > 0) {
    46	            lines.add(l.discount() + ": " + l.money().apply(quote.discount()));
    47	        }
    48	        lines.add(l.total() + ": " + l.money().apply(quote.total()));
    49	        lines.addAll(footerLines);
    50	        return String.join("\n", lines);
    51	    }
    52	}
