     1	package pousada.identity;
     2	
     3	import java.util.ArrayList;
     4	import java.util.LinkedHashMap;
     5	import java.util.List;
     6	import java.util.Map;
     7	import java.util.function.Function;
     8	
     9	import com.fasterxml.jackson.databind.JsonNode;
    10	
    11	import pousada.ApiException;
    12	
    13	/** Registro das formas de identificação. Uma nova forma entra só na lista ALL. */
    14	public final class IdentityKinds {
    15	    private static final List<IdentityKind> ALL = List.of(
    16	            CpfIdentity.KIND,
    17	            CnpjIdentity.KIND,
    18	            PassportIdentity.KIND);
    19	
    20	    private IdentityKinds() {
    21	    }
    22	
    23	    /** Todos os campos de identificação que a API expõe, na ordem de registro. */
    24	    public static List<String> fieldNames() {
    25	        return ALL.stream().flatMap(k -> k.fields().stream()).toList();
    26	    }
    27	
    28	    /** Campos de identificação para JSON, com null nos que não se aplicam. */
    29	    public static Map<String, String> toJsonFields(GuestIdentity identity) {
    30	        Map<String, String> result = new LinkedHashMap<>();
    31	        Map<String, String> own = identity.fields();
    32	        for (String name : fieldNames()) {
    33	            result.put(name, own.get(name));
    34	        }
    35	        return result;
    36	    }
    37	
    38	    /** Lê do corpo da requisição exatamente uma forma de identificação completa. */
    39	    public static GuestIdentity parse(JsonNode body) {
    40	        List<GuestIdentity> found = new ArrayList<>();
    41	        for (IdentityKind kind : ALL) {
    42	            Map<String, String> values = new LinkedHashMap<>();
    43	            for (String field : kind.fields()) {
    44	                String value = textOrNull(body.get(field), field);
    45	                if (value != null) {
    46	                    values.put(field, value);
    47	                }
    48	            }
    49	            if (values.isEmpty()) {
    50	                continue;
    51	            }
    52	            if (values.size() != kind.fields().size()) {
    53	                throw ApiException.invalid("Identificação incompleta: informe " + kind.fields() + ".");
    54	            }
    55	            found.add(kind.create(values));
    56	        }
    57	        if (found.size() != 1) {
    58	            throw ApiException.invalid("Informe exatamente uma identificação: " + ALL.stream().map(IdentityKind::fields).toList() + ".");
    59	        }
    60	        return found.get(0);
    61	    }
    62	
    63	    private static String textOrNull(JsonNode node, String field) {
    64	        if (node == null || node.isNull()) {
    65	            return null;
    66	        }
    67	        if (!node.isTextual()) {
    68	            throw ApiException.invalid("O campo " + field + " deve ser texto.");
    69	        }
    70	        String text = node.asText().trim();
    71	        return text.isEmpty() ? null : text;
    72	    }
    73	}
