    15	import pousada.identity.IdentityKinds;
    16	
    17	public final class App {
    18	    private static final ObjectMapper MAPPER = new ObjectMapper();
    19	    private static final String CSV = "text/csv; charset=utf-8";
    20	
    21	    private final ReservationService service;
    22	    private final Outbox outbox;
    23	
    24	    public App(ReservationService service, Outbox outbox) {
    25	        this.service = service;
    26	        this.outbox = outbox;
    27	    }
    28	
    29	    public static Javalin create() {
    30	        Outbox outbox = new Outbox();
    31	        return new App(new ReservationService(outbox), outbox).routes();
    32	    }
    33	
    34	    private Javalin routes() {
    35	        Javalin app = Javalin.create();
    36	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
    37	        app.exception(Exception.class, (e, ctx) -> error(ctx, 500, "INTERNAL_ERROR", "Erro interno."));
    38	
    39	        app.get("/rooms", ctx -> ctx.json(RoomCatalog.all().stream().map(App::roomView).toList()));
    40	        app.post("/reservations", ctx -> {
    41	            Reservation r = ReservationRequest.parse(readBody(ctx), service);
