    15	    static Reservation parse(JsonNode body, ReservationService service) {
    16	        int roomNumber = integer(body, "roomNumber");
    17	        String guestName = text(body, "guestName");
    18	        String guestEmail = text(body, "guestEmail");
    19	        LocalDate checkIn = date(body, "checkIn");
    20	        LocalDate checkOut = date(body, "checkOut");
    21	        int guests = integer(body, "guests");
    22	        RatePlan ratePlan = ratePlan(body);
    23	        var identity = IdentityKinds.parse(body);
    24	        if (!checkOut.isAfter(checkIn)) {
    25	            throw ApiException.invalid("A saída deve ser depois da entrada.");
    26	        }
    27	        if (guests < 1) {
    28	            throw ApiException.invalid("Informe pelo menos um hóspede.");
    29	        }
    30	        return service.create(roomNumber, guestName, guestEmail, identity, checkIn, checkOut, guests, ratePlan);
    31	    }
