    10	public class ReservationService {
    11	    private static final String CONFIRMATION_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
    12	
    13	    private final List<Reservation> reservations = new ArrayList<>();
    14	    private final Outbox outbox;
    15	
    16	    public ReservationService(Outbox outbox) {
    17	        this.outbox = outbox;
    18	    }
    19	
    20	    public synchronized Reservation create(int roomNumber, String guestName, String guestEmail, GuestIdentity identity,
    21	                                           LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    22	        Room room = RoomCatalog.find(roomNumber)
    23	                .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + roomNumber + " não existe."));
    24	        if (guests > room.capacity()) {
    25	            throw new ApiException(422, "CAPACITY_EXCEEDED",
    26	                    "O quarto " + roomNumber + " comporta no máximo " + room.capacity() + " pessoas.");
    27	        }
    28	        boolean taken = reservations.stream()
    29	                .anyMatch(r -> r.room().equals(room)
    30	                        && r.status() != ReservationStatus.CANCELLED
    31	                        && r.overlaps(checkIn, checkOut));
    32	        if (taken) {
    33	            throw new ApiException(409, "ROOM_UNAVAILABLE", "O quarto " + roomNumber + " já está reservado nesse período.");
    34	        }
    35	        Reservation reservation = new Reservation(reservations.size() + 1, room, guestName, guestEmail, identity,
    36	                checkIn, checkOut, guests, ratePlan);
    37	        reservations.add(reservation);
    38	        return reservation;
    39	    }
    40	
    41	    public synchronized Reservation get(int id) {
    42	        if (id < 1 || id > reservations.size()) {
    43	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe.");
    44	        }
    45	        return reservations.get(id - 1);
    46	    }
    47	
    48	    public synchronized List<Reservation> all() {
    49	        return List.copyOf(reservations);
    50	    }
    51	
    52	    public synchronized Reservation confirm(int id) {
    53	        Reservation reservation = get(id);
    54	        reservation.confirm();
    55	        outbox.sendEmail(reservation.guestEmail(), CONFIRMATION_SUBJECT, confirmationBody(reservation));
    56	        return reservation;
    57	    }
    58	
    59	    public synchronized Reservation cancel(int id) {
    60	        Reservation reservation = get(id);
    61	        reservation.cancel();
    62	        return reservation;
    63	    }
    64	
    65	    public synchronized Reservation checkIn(int id) {
    66	        Reservation reservation = get(id);
    67	        reservation.startStay();
    68	        return reservation;
    69	    }
    70	
    71	    public synchronized Reservation checkOut(int id) {
    72	        Reservation reservation = get(id);
    73	        reservation.endStay();
    74	        return reservation;
    75	    }
    76	
    77	    /** Segunda via: só existe para reserva paga. */
    78	    public synchronized Reservation paidReservation(int id) {
    79	        Reservation reservation = get(id);
    80	        if (!reservation.status().isPaid()) {
    81	            throw ApiException.notAllowed("A reserva " + id + " está " + reservation.status() + " e não tem documento.");
    82	        }
    83	        return reservation;
    84	    }
